INSERT INTO quiz_questions (module_id, question, option_a, option_b, option_c, option_d, correct_answer, explanation, sort_order) VALUES
('01884014-4989-488a-8a1b-e45855c195f8', 'Was ist High-Ticket Closing?', 'Günstige Produkte schnell verkaufen', 'Premium-Angebote durch gezielte Gesprächsführung zum Abschluss bringen', 'Kunden unter Druck setzen', 'Möglichst viele Anrufe pro Tag machen', 'B', 'High-Ticket Closing bedeutet, hochpreisige Angebote durch professionelle, ethische Gesprächsführung zum Abschluss zu bringen — nicht durch Druck, sondern durch Vertrauen und Klarheit.', 1);
INSERT INTO quiz_questions (module_id, question, option_a, option_b, option_c, option_d, correct_answer, explanation, sort_order) VALUES
('559b59a5-f71c-4b0b-a321-5624d4d8eb77', 'Was ist der Buying Process?', 'Ein Verkaufsskript, das man auswendig lernt', 'Der psychologische Entscheidungsprozess, den ein Kunde durchläuft', 'Eine Liste von Einwänden', 'Die Preisverhandlung am Ende', 'B', 'Der Buying Process beschreibt die inneren Phasen, die ein Mensch durchläuft, bevor er eine Kaufentscheidung trifft — von Awareness über Consideration bis Decision. Verstehst du diesen Prozess, kannst du den Kunden besser begleiten.', 1);
INSERT INTO quiz_questions (module_id, question, option_a, option_b, option_c, option_d, correct_answer, explanation, sort_order) VALUES
('fb8028cf-608c-4efa-8006-d0b0c6f2fa53', 'Was ist Rapport?', 'Eine Verkaufstechnik zum Manipulieren', 'Eine echte, vertrauensvolle Verbindung zwischen Gesprächspartnern', 'Smalltalk am Anfang des Gesprächs', 'Dem Kunden immer Recht geben', 'B', 'Rapport ist wie ein unsichtbares Band zwischen dir und deinem Gesprächspartner. Wenn Rapport da ist, fühlt sich der andere verstanden und gehört — und nur dann kann ein ehrliches Gespräch entstehen.', 1);
INSERT INTO quiz_questions (module_id, question, option_a, option_b, option_c, option_d, correct_answer, explanation, sort_order) VALUES
('d83f1c4a-315c-4079-93ac-2573bd7c062c', 'Was bedeutet aktives Zuhören?', 'Warten, bis der andere fertig ist, um zu antworten', 'Dem Gesprächspartner mit voller Aufmerksamkeit zuhören und das Gesagte reflektieren', 'Alles mitschreiben', 'Nicken und lächeln', 'B', 'Aktives Zuhören bedeutet nicht nur schweigen, sondern wirklich verstehen. Du hörst nicht nur die Worte, sondern auch die Emotionen dahinter — und zeigst dem anderen, dass du ihn verstanden hast, indem du das Gehörte in eigenen Worten wiedergibst.', 1);
INSERT INTO quiz_questions (module_id, question, option_a, option_b, option_c, option_d, correct_answer, explanation, sort_order) VALUES
('cf3427b5-771e-4c8b-b2f6-dea68a3a9625', 'Was ist Reframing?', 'Dem Kunden widersprechen', 'Eine Situation aus einer neuen, hilfreicheren Perspektive betrachten lassen', 'Den Preis senken', 'Das Gespräch beenden', 'B', 'Stell dir vor, jemand sagt: Das ist zu teuer. Reframing bedeutet nicht, den Preis zu ändern, sondern die Perspektive: Was kostet es dich, wenn du nichts änderst? Du hilfst dem anderen, das Bild neu zu sehen.', 1);
INSERT INTO quiz_questions (module_id, question, option_a, option_b, option_c, option_d, correct_answer, explanation, sort_order) VALUES
('23663e29-618b-4d1f-bcc5-1bbed443fe35', 'Was ist der häufigste Grund hinter einem Preis-Einwand?', 'Die Person hat wirklich kein Geld', 'Der Wert des Angebots ist noch nicht klar genug', 'Das Produkt ist objektiv zu teuer', 'Die Person will nur verhandeln', 'B', 'Wenn jemand sagt, etwas sei zu teuer, bedeutet das fast immer: Ich sehe noch nicht klar genug, was ich dafür bekomme. Das ist keine Preis-Frage — das ist eine Wert-Frage. Mach den Wert sichtbar, nicht den Preis kleiner.', 1);
INSERT INTO quiz_questions (module_id, question, option_a, option_b, option_c, option_d, correct_answer, explanation, sort_order) VALUES
('d7fc4d35-2be2-4b0e-8ccd-45a62dfcb94f', 'Was ist der wichtigste Schritt vor deinem ersten Live-Gespräch?', 'Das Skript auswendig lernen', 'Dich mental und emotional vorbereiten und deine Intention setzen', 'Möglichst viel über den Kunden googlen', 'Einen Rabatt vorbereiten', 'B', 'Dein Zustand bestimmt die Qualität des Gesprächs. Wenn du nervös und unvorbereitet bist, spürt das dein Gegenüber. Mentale Vorbereitung, eine klare Intention und emotionale Erdung sind wichtiger als jedes Skript.', 1);
INSERT INTO quiz_questions (module_id, question, option_a, option_b, option_c, option_d, correct_answer, explanation, sort_order) VALUES
('bb68a590-497c-4284-a9e4-aaffc3c11471', 'Wie solltest du mit Feedback nach einem Gespräch umgehen?', 'Feedback ignorieren und weiter machen', 'Feedback als Lernchance sehen und konkrete Verbesserungen ableiten', 'Nur positives Feedback annehmen', 'Sich rechtfertigen', 'B', 'Feedback ist wie ein Spiegel — es zeigt dir Dinge, die du selbst nicht siehst. Die besten Closer nehmen jedes Feedback ernst, suchen den Kern der Wahrheit und leiten eine konkrete Verbesserung daraus ab.', 1);